WITH RankedPosts AS (
    SELECT
        p.Id,
        p.Title,
        p.OwnerUserId,
        p.PostTypeId,
        p.Score,
        p.CreationDate,
        ROW_NUMBER() OVER (
            PARTITION BY p.PostTypeId 
            ORDER BY p.Score DESC, p.CreationDate ASC
        ) AS ScoreRank,
        CASE 
            WHEN p.Tags IS NULL THEN ARRAY[]::varchar[]
            ELSE string_to_array(substring(p.Tags from 2 for length(p.Tags) - 2), '><')
        END AS SplitTags
    FROM Posts p
    WHERE p.PostTypeId IN (1, 2) -- Only Questions and Answers
),
